import { StatusBar } from 'expo-status-bar';
import { StyleSheet, Text, View, WebView, Alert, ActivityIndicator, ScrollView} from 'react-native';
import React, { useState, useEffect } from 'react';

import SpotSectors from "../../components/Routes_and_sectors/spot_sectors";

import axios from 'axios'

export default function App({route}) {
  const [outdoor_data, setOutdoorData] = useState([])

  useEffect(() => {
    // const getData = () => {
      axios
      .get('https://climbing.ge/api/article/outdoor/us/' + route.params )
      .then(function( data ){
        setOutdoorData(data);
        console.log('====================================');
        console.log(outdoor_data);
        console.log('===================================='); 
      })
      .catch(error => {
        console.log(error);
        Alert.alert('ERROR!', 'Axios request is fale')
      })
      .finally(function () {
        alert('Finally called');
      });
    // };

    // getData()

  }, []);

  return (
    <ScrollView style={styles.container}>

      <SpotSectors article_id={route.params} />

      <StatusBar style="auto" />
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
  },
  h1: {
    fontSize: 26
  },
  h2: {
    fontSize: 20
  }
});
